import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_kernel_code = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void fused_max_pool_sum_kernel(
    const float* input,
    float* output,
    int total_output_elements,
    int batch_size,
    int channels,
    int input_depth,
    int input_height,
    int input_width,
    int output_depth,
    int output_height,
    int output_width
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total_output_elements) return;

    int b = idx / (output_depth * output_height * output_width);
    int remaining = idx % (output_depth * output_height * output_width);
    int d_out = remaining / (output_height * output_width);
    remaining = remaining % (output_height * output_width);
    int h_out = remaining / output_width;
    int w_out = remaining % output_width;

    if (b >= batch_size) return;

    float sum = 0.0f;

    for (int c = 0; c < channels; ++c) {
        float max_val = -INFINITY;

        // Second max pool window
        for (int d1 = 0; d1 < 3; ++d1) {
            int d_pool1 = d_out * 3 + d1;
            if (d_pool1 >= (input_depth / 2)) break;

            for (int h1 = 0; h1 < 3; ++h1) {
                int h_pool1 = h_out * 3 + h1;
                if (h_pool1 >= (input_height / 2)) break;

                for (int w1 = 0; w1 < 3; ++w1) {
                    int w_pool1 = w_out * 3 + w1;
                    if (w_pool1 >= (input_width / 2)) break;

                    // First max pool window
                    float local_max = -INFINITY;
                    for (int dd = 0; dd < 2; ++dd) {
                        int d_in = d_pool1 * 2 + dd;
                        if (d_in >= input_depth) break;
                        for (int hh = 0; hh < 2; ++hh) {
                            int h_in = h_pool1 * 2 + hh;
                            if (h_in >= input_height) break;
                            for (int ww = 0; ww < 2; ++ww) {
                                int w_in = w_pool1 * 2 + ww;
                                if (w_in >= input_width) break;

                                int input_idx = b * channels * input_depth * input_height * input_width +
                                            c * input_depth * input_height * input_width +
                                            d_in * input_height * input_width +
                                            h_in * input_width +
                                            w_in;
                                float val = __ldg(input + input_idx);
                                local_max = fmaxf(local_max, val);
                            }
                        }
                    }

                    max_val = fmaxf(max_val, local_max);
                }
            }
        }

        sum += max_val;
    }

    int output_idx = b * output_depth * output_height * output_width +
                    d_out * output_height * output_width +
                    h_out * output_width +
                    w_out;
    output[output_idx] = sum;
}

torch::Tensor fused_max_pool_sum_cuda(torch::Tensor input) {
    auto batch_size = input.size(0);
    auto channels = input.size(1);
    auto input_depth = input.size(2);
    auto input_height = input.size(3);
    auto input_width = input.size(4);

    int output_depth = (input_depth / 2) / 3;
    int output_height = (input_height / 2) / 3;
    int output_width = (input_width / 2) / 3;

    auto output = torch::zeros({batch_size, 1, output_depth, output_height, output_width}, input.options());

    int total_output_elements = batch_size * output_depth * output_height * output_width;
    int threads_per_block = 256;
    int num_blocks = (total_output_elements + threads_per_block - 1) / threads_per_block;

    fused_max_pool_sum_kernel<<<num_blocks, threads_per_block>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        total_output_elements,
        batch_size,
        channels,
        input_depth,
        input_height,
        input_width,
        output_depth,
        output_height,
        output_width
    );

    return output;
}
"""

fused_kernel_cpp = """
torch::Tensor fused_max_pool_sum_cuda(torch::Tensor input);
"""

fused_max_pool_sum = load_inline(
    name='fused_max_pool_sum',
    cpp_sources=fused_kernel_cpp,
    cuda_sources=fused_kernel_code,
    functions=['fused_max_pool_sum_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose3d(in_channels, out_channels, kernel_size, stride=stride, padding=padding)
        self.fused_op = fused_max_pool_sum

    def forward(self, x):
        x = self.conv_transpose(x)
        x = self.fused_op.fused_max_pool_sum_cuda(x)
        return x
